import csv, hashlib, json, re
from collections import Counter
from pathlib import Path
import yaml

P = Path(__file__).resolve().parents[1]
A = P / 'audit'
def read(p): return yaml.safe_load(p.read_text(encoding='utf-8'))
def write(name, text): (A/name).write_text(text, encoding='utf-8')
def csvout(name, rows):
    with (A/name).open('w', encoding='utf-8-sig', newline='') as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
rules = [read(x) for x in sorted((P/'rules').glob('*.yaml'))]
sources = json.loads((P/'sources.json').read_text(encoding='utf-8'))
fetches = {x['source_id']: x for x in json.loads((A/'external_fetch_results.json').read_text(encoding='utf-8'))}
findings = []
def finding(id, severity, file, claim, source, fact, impact, fix, status='подтверждено'):
    findings.append(dict(ID=id, criticality=severity, file_rule_locator=file, checked_claim=claim,
                         source_version_locator=source, established_fact=fact, impact=impact,
                         required_fix=fix, status=status))
