cardrows=[]; paramrows=[]; conditionrows=[]; caserows=[]
for r in rules:
    rid=r['rule_id']; group=rid.split('-')[0]; ids={i['input_id'] for i in r['inputs']}
    refs=sorted({x['source_ref'] for x in r['clinical_parameters']} | set(r['applicability'].get('source_refs',[])))
    cardrows.append(dict(rule_id=rid, identity=json.dumps(r['identity'],ensure_ascii=False), parameters=len(r['clinical_parameters']),
        inputs=len(r['inputs']), expectations=len(r['test_cases']), ready_claim=r['verification']['ready_for_technical_implementation'],
        sources=';'.join(refs), independent_review=group_notes[group],
        transfer_decision='Только после исправления/явного ограничения контракта; ready-флаг не разрешение применения'))
    for x in r['clinical_parameters']:
        status='число/единица сверены с доступным оригиналом; условия результата проверять отдельно'
        if x['source_ref']=='RU-ESC': status='не удалось проверить актуальный оригинал; не подтверждено'
        if 'taper' in rid and (x.get('upper')==2 or x.get('value')==[1,2]): status='исходные числа совпадают; неверно/неоднозначно представлен минимальный смысл (F03)'
        paramrows.append(dict(rule_id=rid,parameter_id=x['parameter_id'],value=json.dumps(x.get('value'),ensure_ascii=False),lower=x.get('lower'),upper=x.get('upper'),unit=x['unit'],
                             meaning=x.get('meaning',''),source=x['source_ref'],locator=x['source_locator'],audit_status=status))
    for k,v in r['applicability'].items():
        if k=='source_refs': continue
        conditionrows.append(dict(rule_id=rid,field=k,original_condition=json.dumps(v,ensure_ascii=False),source_refs=';'.join(refs),
                                  audit_conclusion=group_notes[group]))
    for c in r['test_cases']:
        required=[i['input_id'] for i in r['inputs'] if i['required_when'] in ['для выбранного расчёта','для индивидуального результата','для этой ветки']]
        missing=sorted(set(required)-set(c['given'])); extra=sorted(set(c['given'])-ids)
        caserows.append(dict(rule_id=rid,case_id=c['case_id'],given=json.dumps(c['given'],ensure_ascii=False),expected=json.dumps(c['expected'],ensure_ascii=False),
                             absent_unconditionally_declared_inputs=';'.join(missing),unmapped_given_keys=';'.join(extra),source_refs=';'.join(c['source_refs']),
                             conclusion='Фрагмент ожидания, не исполненный тест. Пропуск поля не доказательство неверной дозы; для полного сценария нужен явный контекст и mapping.'))
csvout('06_card_review.csv',cardrows); csvout('06_parameter_review.csv',paramrows); csvout('06_condition_review.csv',conditionrows); csvout('07_case_contract_review.csv',caserows)

