srows=[]
for sid,s in sources.items():
    f=fetches.get(sid,{})
    status=str(f.get('status',f.get('error','нет отдельного повторного скачивания')))
    result='Повторный доступ подтверждает копию/страницу, не последнюю утверждённую редакцию реестра'
    if f.get('equals_research_hash') is True: result='Скачанные байты совпали с исходным SHA; это воспроизведение копии, не медицинская актуальность'
    if sid in ['RU-GAD','RU-PANIC','RU-PHOB','RU-DEP']: result+='; текущий CodeVersion/ApplyStatusCalculated=1 подтверждён свежим каталогом Минздрава'
    if sid=='RU-ESC': result='Не удалось независимо подтвердить актуальное основание; архивная копия не заменяет оригинал'
    srows.append(dict(source_id=sid,organization=s['organization_or_authors'],version_claim=s['version_or_update_date'],
        url=s['url'],access_on='2026-10-08',independent_access=status,sha256=f.get('sha256',''),same_bytes=f.get('equals_research_hash',''),
        parts_read=parts.get(sid,'метаданные/применимость, полного медицинского чтения не заявлено'),
        unverified_parts='Не заявляется полное чтение всего документа/фармаконадзора; последняя регистрационная редакция не независимо сопоставлена, кроме свежего статуса указанных КР',conclusion=result))
csvout('03_source_verification.csv',srows)

